export function getPostBySlug(slug: string): Post | undefined {
  return posts.find((p) => p.slug === slug);
}

export function getRelatedPosts(post: Post, count = 3): Post[] {
  return posts
    .filter((p) => p.slug !== post.slug && p.category === post.category)
    .slice(0, count)
    .concat(
      posts
        .filter((p) => p.slug !== post.slug && p.category !== post.category)
        .slice(0, count)
    )
    .slice(0, count);
}
